import Animated, {
	runOnJS,
	useAnimatedStyle,
	useSharedValue,
	withRepeat,
	withTiming
} from 'react-native-reanimated'
import { LinearGradient } from 'expo-linear-gradient'
import { useEffect } from 'react'
import { colors, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'

const SHINE_DURATION = 2000 // how long the shine animation lasts

type ShineEffectProps = {
	shineCondition: boolean // while this is true, the shine effect will run
	shineWidth: number
	onAnimationComplete: () => void
}

export const ShineEffect = ({
	shineCondition,
	shineWidth,
	onAnimationComplete
}: ShineEffectProps) => {
	const { theme } = useTheme()

	const SHINE_TRAVEL_DISTANCE = shineWidth * 2

	const shineAnimation = useSharedValue(0)

	const shineStyle = useAnimatedStyle(() => ({
		transform: [{ translateX: shineAnimation.get() }]
	}))

	const animate = () => {
		shineAnimation.set(
			withRepeat(
				withTiming(SHINE_TRAVEL_DISTANCE, { duration: SHINE_DURATION }, () => {
					if (!shineCondition) {
						runOnJS(onAnimationComplete)()
					}
				}),
				-1,
				false
			)
		)
	}

	useEffect(() => {
		animate()
	}, [animate])

	return (
		<Animated.View
			style={[shineStyle, styles.shineEffect, { left: -shineWidth }]}
		>
			<LinearGradient
				colors={[
					`${colors[theme].background}00`,
					`${colors[theme].background}cc`, // 80% opacity
					`${colors[theme].background}00`
				]}
				style={[styles.shineEffectGradient, { width: shineWidth }]}
				start={{ x: 0, y: 0 }}
				end={{ x: 1, y: 0 }}
			/>
		</Animated.View>
	)
}

const styles = defineStyles({
	shineEffect: {
		position: 'absolute',
		top: 0,
		right: 0,
		bottom: 0,
		zIndex: 15
	},
	shineEffectGradient: {
		height: '100%'
	}
})
